80	impl StagedAdd {
81	    /// `residual add <subcommand>` name as clap spells it (kebab-case).
82	    pub fn subcommand(&self) -> &'static str {
83	        match self {
84	            StagedAdd::Stressor { .. } => "stressor",
85	            StagedAdd::Purpose { .. } => "purpose",
86	            StagedAdd::Attractor { .. } => "attractor",
87	            StagedAdd::Component { .. } => "component",
88	            StagedAdd::MetaStressor { .. } => "meta-stressor",
89	            StagedAdd::MetaAttractor { .. } => "meta-attractor",
90	            StagedAdd::MetaPurpose { .. } => "meta-purpose",
91	            StagedAdd::DefensePersona { .. } => "defense-persona",
92	            StagedAdd::DefenseStrategy { .. } => "defense-strategy",
93	            StagedAdd::DefenseProgress { .. } => "defense-progress",
94	            StagedAdd::DefensePitch { .. } => "defense-pitch",
95	        }
96	    }
97	
98	    /// True for variants that only belong in a `--defense` landscape.
99	    pub fn is_defense(&self) -> bool {
100	        matches!(
101	            self,
102	            StagedAdd::MetaStressor { .. }
103	                | StagedAdd::MetaAttractor { .. }
104	                | StagedAdd::MetaPurpose { .. }
105	                | StagedAdd::DefensePersona { .. }
106	                | StagedAdd::DefenseStrategy { .. }
107	                | StagedAdd::DefenseProgress { .. }
108	                | StagedAdd::DefensePitch { .. }
109	        )
110	    }
111	}
