113	/// Quote a value for safe copy-paste into a shell.
114	///
115	/// Single-line values use POSIX single quotes (`'\''` for embedded apostrophes).
116	/// Values containing newlines use ANSI-C `$'…'` quoting so the whole argument
117	/// stays on one command line.
118	pub fn shell_quote(value: &str) -> String {
119	    if value.contains('\n') {
120	        let mut escaped = String::with_capacity(value.len() + 8);
121	        for ch in value.chars() {
122	            match ch {
123	                '\\' => escaped.push_str("\\\\"),
124	                '\'' => escaped.push_str("\\'"),
125	                '\n' => escaped.push_str("\\n"),
126	                '\r' => escaped.push_str("\\r"),
127	                '\t' => escaped.push_str("\\t"),
128	                c => escaped.push(c),
129	            }
130	        }
131	        format!("$'{escaped}'")
132	    } else {
133	        format!("'{}'", value.replace('\'', "'\\''"))
134	    }
135	}
136	
137	fn push_flag(parts: &mut Vec<String>, flag: &str, value: &str) {
138	    parts.push(format!("{flag} {}", shell_quote(value)));
139	}
140	
141	fn push_optional_flag(parts: &mut Vec<String>, flag: &str, value: &str) {
142	    if !value.is_empty() {
143	        push_flag(parts, flag, value);
144	    }
145	}
