181	            negative_state,
182	        } => {
183	            push_flag(&mut parts, "--name", name);
184	            push_flag(&mut parts, "--description", description);
185	            push_flag(&mut parts, "--positive-state", positive_state);
186	            push_flag(&mut parts, "--negative-state", negative_state);
187	        }
188	        StagedAdd::Component {
189	            name,
190	            description,
191	            status,
192	            architecture_set,
193	        } => {
194	            push_flag(&mut parts, "--name", name);
195	            push_flag(&mut parts, "--description", description);
196	            push_flag(&mut parts, "--status", status);
197	            push_flag(&mut parts, "--architecture-set", architecture_set);
198	        }
199	        StagedAdd::MetaStressor {
200	            description,
201	            shortname,
202	        } => {
203	            push_flag(&mut parts, "--description", description);
204	            push_optional_flag(&mut parts, "--shortname", shortname);
205	        }
206	        StagedAdd::MetaAttractor {
207	            name,
208	            description,
209	            positive_state,
210	            negative_state,
211	        } => {
212	            push_flag(&mut parts, "--name", name);
213	            push_flag(&mut parts, "--description", description);
214	            push_flag(&mut parts, "--positive-state", positive_state);
215	            push_flag(&mut parts, "--negative-state", negative_state);
216	        }
217	        StagedAdd::MetaPurpose {
218	            description,
219	            attractor_id,
220	            naive_change,
221	            shortname,
222	            outcomes,
223	        } => {
224	            push_flag(&mut parts, "--description", description);
225	            push_flag(&mut parts, "--attractor-id", attractor_id);
226	            push_flag(&mut parts, "--naive-change", naive_change);
227	            push_optional_flag(&mut parts, "--shortname", shortname);
228	            push_optional_flag(&mut parts, "--outcomes", outcomes);
229	        }
230	        StagedAdd::DefensePersona { name, body }
231	        | StagedAdd::DefenseStrategy { name, body }
232	        | StagedAdd::DefenseProgress { name, body }
233	        | StagedAdd::DefensePitch { name, body } => {
234	            push_flag(&mut parts, "--name", name);
235	            push_flag(&mut parts, "--body", body);
236	        }
237	    }
238	    parts.join(" ")
239	}
