1	//! Landscape view — read-only HTML rendering of the residual ledger.
2	//!
3	//! `residual view` writes a self-contained page to a temp dir (or `--out`) and
4	//! prints the path. `residual serve` hands the same page out over loopback.
5	//! Neither mutates the ledger: the page stages `residual add …` commands that
6	//! the operator copies and runs.
7	
8	pub mod commands;
9	pub mod html;
10	pub mod snapshot;
11	
12	use anyhow::{anyhow, Context, Result};
13	use std::path::PathBuf;
14	
15	use crate::config::Config;
16	
17	#[allow(unused_imports)] // re-exports for green agents / external callers
18	pub use commands::{format_add_command, format_add_commands, StagedAdd};
19	pub use html::render_landscape_html;
20	#[allow(unused_imports)] // re-exports for green agents / external callers
21	pub use snapshot::{
22	    load_landscape_snapshot, load_landscape_snapshot_from_dir, load_landscape_snapshot_from_sources,
23	    resolve_sources, LandscapeSnapshot, LandscapeSources,
24	};
25	
26	/// Filename written into the output directory.
27	pub const LANDSCAPE_FILENAME: &str = "landscape.html";
28	
29	/// Loopback host the landscape binds to. Never 0.0.0.0: the ledger is not public.
30	pub const SERVE_HOST: &str = "127.0.0.1";
31	
32	/// Default port for `residual serve` when `--port` is omitted.
33	pub const DEFAULT_PORT: u16 = 8787;
34	
35	#[derive(Debug, Clone, Default, PartialEq, Eq)]
36	pub struct ViewOptions {
37	    /// Include the defense ledger (meta forces + defense artifacts).
38	    pub include_defense: bool,
39	    /// Destination directory. `None` means the system temp dir (ephemeral, uncommitted).
40	    pub out_dir: Option<PathBuf>,
41	}
42	
43	/// What the server hands out: the page at `/`, the raw snapshot at `/snapshot.json`.
44	#[derive(Debug, Clone, PartialEq, Eq)]
45	pub struct ServeDocument {
46	    pub html: String,
47	    pub snapshot_json: String,
48	}
49	
50	/// Render the landscape and write it to disk. Returns the written HTML path.
51	pub fn write_landscape_html(cfg: &Config, opts: &ViewOptions) -> Result<PathBuf> {
52	    let snap = load_landscape_snapshot(cfg, opts.include_defense)?;
53	    let html = render_landscape_html(&snap)?;
54	
55	    let out_dir = match &opts.out_dir {
56	        Some(dir) => {
57	            std::fs::create_dir_all(dir)
58	                .with_context(|| format!("creating landscape out dir {}", dir.display()))?;
59	            dir.clone()
60	        }
61	        None => std::env::temp_dir(),
62	    };
63	
64	    let path = absolutize(out_dir.join(LANDSCAPE_FILENAME))?;
65	    std::fs::write(&path, html)
66	        .with_context(|| format!("writing landscape html to {}", path.display()))?;
67	    Ok(path)
68	}
69	
70	/// `residual view` entry point — writes the page and prints its path.
71	pub fn run_view(cfg: &Config, include_defense: bool, out_dir: Option<PathBuf>) -> Result<()> {
72	    let path = write_landscape_html(
73	        cfg,
74	        &ViewOptions {
75	            include_defense,
76	            out_dir,
77	        },
78	    )?;
79	    println!("{}", path.display());
80	    Ok(())
81	}
82	
83	/// Printable URL for a bound port.
84	pub fn serve_url(port: u16) -> String {
85	    format!("http://{SERVE_HOST}:{port}/")
86	}
87	
88	/// Build the served payload without binding a socket.
89	pub fn build_serve_document(cfg: &Config, include_defense: bool) -> Result<ServeDocument> {
90	    let snap = load_landscape_snapshot(cfg, include_defense)?;
91	    let html = render_landscape_html(&snap)?;
92	    let snapshot_json = snap.to_json()?;
93	    Ok(ServeDocument {
94	        html,
95	        snapshot_json,
96	    })
97	}
98	
99	/// Bind the loopback listener and block. Prints the URL before serving.
100	pub fn run_serve(cfg: &Config, include_defense: bool, port: u16) -> Result<()> {
101	    let doc = build_serve_document(cfg, include_defense)?;
102	    let url = serve_url(port);
103	    println!("{url}");
104	
105	    let addr = format!("{SERVE_HOST}:{port}");
106	    let server = tiny_http::Server::http(&addr)
107	        .map_err(|e| anyhow!("binding landscape server on {addr}: {e}"))?;
108	
109	    for request in server.incoming_requests() {
110	        let path = request.url().split('?').next().unwrap_or("/");
111	        let response = match path {
112	            "/" | "" => tiny_http::Response::from_data(doc.html.as_bytes())
113	                .with_header(content_type("text/html; charset=utf-8")),
114	            "/snapshot.json" => tiny_http::Response::from_data(doc.snapshot_json.as_bytes())
115	                .with_header(content_type("application/json; charset=utf-8")),
116	            _ => tiny_http::Response::from_string("not found")
117	                .with_status_code(404)
118	                .with_header(content_type("text/plain; charset=utf-8")),
119	        };
120	        // Keep serving even if a single client disconnects mid-write.
121	        let _ = request.respond(response);
122	    }
123	    Ok(())
124	}
125	
126	fn content_type(value: &str) -> tiny_http::Header {
127	    // Header values are ascii; the types we pass are literals.
128	    tiny_http::Header::from_bytes(&b"Content-Type"[..], value.as_bytes())
129	        .expect("Content-Type header is valid ascii")
130	}
131	
132	fn absolutize(path: PathBuf) -> Result<PathBuf> {
133	    if path.is_absolute() {
134	        Ok(path)
135	    } else {
136	        Ok(std::env::current_dir()
137	            .context("resolving current dir for landscape path")?
138	            .join(path))
139	    }
140	}
